/* Shared real-model completed/pending Daily fixtures for SQL compatibility tests. */
const fs=require('node:fs'),vm=require('node:vm');
for(const name of ['codebreak','pack','laser','inner-clock','time-drop','clue-ladder','seating-chart','shift-work'])require('../../'+name+'-model.js');
const clone=structuredClone;
function bank(file,key){const c={window:{}};vm.runInNewContext(fs.readFileSync(file,'utf8'),c);return JSON.parse(JSON.stringify(c.window[key]));}
function fixtures(day){const out=[];
 const C=BREAK_ROOM_CODEBREAK,code=C.create(day),loss=C.create(day);C.draft(code,code.code);C.submit(code);for(const g of C.CODES.filter(x=>x!==loss.code).slice(0,8)){C.draft(loss,g);C.submit(loss);}out.push({game:'codebreak',key:C.PREFIX+day,pending:C.create(day),done:code,zero:loss});
 const P=BREAK_ROOM_PACK,bags=P.daily(bank('games/pack/puzzles.js','PACK_PUZZLES'),day),picks=bags.map(b=>P.solve(b).mask);out.push({game:'pack',key:P.PREFIX+day,pending:{version:1,day,round:0,phase:'play',selection:0,picks:[],bags},done:{version:1,day,round:2,phase:'review',selection:picks[2],picks,bags}});
 const L=BREAK_ROOM_LASER,boards=L.daily(bank('games/laser/boards.js','LASER_BOARDS'),day),mirrors=boards.map(b=>L.solve(b)[0]);out.push({game:'laser',key:L.PREFIX+day,pending:{version:1,day,round:0,phase:'play',edits:0,picks:[],boards,mirrors:[]},done:{version:1,day,round:3,phase:'review',edits:0,picks:mirrors,boards,mirrors:mirrors[3]}});
 const I=BREAK_ROOM_INNER_CLOCK,targets=I.daily(day),clock={version:1,day,round:4,phase:'review',edits:0,targets,picks:targets.map(elapsed=>({elapsed,kind:'stop'})),startedAt:null};out.push({game:'inner-clock',key:I.PREFIX+day,pending:{...clone(clock),round:0,phase:'ready',picks:[]},done:clock,zero:{...clone(clock),picks:targets.map(()=>({elapsed:30000,kind:'timeout'}))}});
 const T=BREAK_ROOM_TIME_DROP,tb=require('../../content/time-drop-events.json').events;function time(zero=false){const r=T.create(tb,day);for(let i=0;i<T.rounds(r);i++){T.guess(r,zero?-4000:r.events[i].year);T.lock(r);if(i<T.rounds(r)-1)T.next(r);}return r;}out.push({game:'time-drop',key:T.PREFIX+day,pending:T.create(tb,day),done:time(),zero:time(true)});
 const CL=BREAK_ROOM_CLUE_LADDER,cb=require('../../content/clue-ladder-puzzles.json').puzzles;function clues(zero=false){const r=CL.create(cb,day);for(let i=0;i<5;i++){if(zero)for(let j=0;j<5;j++)CL.submit(r,null);else CL.submit(r,r.puzzles[i].answer);if(i<4)CL.next(r);}return r;}out.push({game:'clue-ladder',key:CL.PREFIX+day,pending:CL.create(cb,day),done:clues(),zero:clues(true)});
 const S=BREAK_ROOM_SEATING_CHART,sb=require('../../content/seating-chart-puzzles.json').tables,s=S.create(sb,day);for(let i=0;i<S.rounds(s);i++){S.edit(s,s.tables[i].solution);S.submit(s);if(i<S.rounds(s)-1)S.next(s);}out.push({game:'seating-chart',key:S.PREFIX+day,pending:S.create(sb,day),done:s});
 const W=BREAK_ROOM_SHIFT_WORK,wb=require('../../content/shift-work-boards.json').boards,w=W.create(W.daily(wb,day),day);for(let i=0;i<3;i++){for(const [piece,move]of W.solve(w.boards[i],w.pos).path)W.apply(w,piece,move);if(i<2)W.next(w);}out.push({game:'shift-work',key:W.PREFIX+day,pending:W.create(W.daily(wb,day),day),done:w});
 const stack=bank('games/stack-up/familiar-stacks.js','STACK_UP_FAMILIAR_STACKS')[0],results=Array.from({length:5},(_,i)=>({correct:true,points:550+35*i,seconds:90,mistakes:0})),st={version:2,scoreVersion:4,day,round:4,score:3100,streak:5,results,order:[1,2,3,4,5],deadline:1,mistakes:0,status:'complete',stacks:Array(5).fill(stack)};out.push({game:'stack-up',key:'break-room:stack-up:daily:'+day,pending:{...clone(st),round:0,score:0,streak:0,results:[],status:'playing'},done:st,zero:{...clone(st),score:-200,streak:0,results:results.map(()=>({correct:false,points:-40,seconds:0,mistakes:0}))}});
 return out;
}
module.exports=fixtures;
